// presti-relances : l'instant du passage. Un passage par jour (8 h, Europe/Paris) ; l'instant sert à deux choses : quelles relances sont
// dues (planifiee_le <= passage, comme app/api/cron/relances/route.ts:64-69) et le calcul du registre commun de 3 jours. Copie figée
// contrôlée par scripts/relances-n8n-qa.mjs ; l'instant vient de Date.now() (le juge le fixe).
const maintenant = Date.now();
const jour = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(maintenant));
return [{ json: { passage: new Date(maintenant).toISOString(), jour, simulation: true } }];

// presti-relances : la DÉCISION des relances de conversation (J+2, J+5, J+10), refaite depuis app/api/cron/relances/route.ts:58-203 et
// lib/relancesRegistre.ts : pour chaque relance due, dans l'ordre de l'ancien passage — lead clos, main prise, offre sans plateforme, compte
// suspendu ou en pause, un seul contact par passage, registre commun de 3 jours, sujet d'escalade, compte de démonstration, puis Studio
// (préparée « à valider ») ou Signature (part seule). Code pur : rien n'est envoyé, rien n'est écrit, aucun modèle n'est appelé.
// Les listes de mots, les expressions et les offres viennent de lib/pilote/regles.ts, lib/plans.ts et lib/plateformeConfig.ts par generer.mjs
// (jamais retapées) ; copie figée contrôlée par scripts/relances-n8n-qa.mjs, qui rejoue la VRAIE route sur des cas fictifs.
const MOTS_TOUJOURS = ["litige","litigieux","sinistre","avocat","menace","mise en demeure","en demeure","plainte","tribunal","tribunaux","huissier","contentieux","conteste","contestation","arnaque","escroquerie","escroc","urgence","fuite","dégât des eaux","dégâts des eaux","dégât d’eau","dégâts d’eau","inondation","inondé","assurance","justice","prud’hom","juridique","médiateur","conciliat","dgccrf","gendarme","préjudice","indemni","dédommag","réclamation","lettre recommandée","recommandé avec","en recommandé","accusé de réception","vice caché","vices cachés","opposition","malfaçon","décennale","expert","dégât","incendie","brûl","blessé","blessure","électrocut","monoxyde","intoxi","effondr","écroul","infiltr","court-circuit","court circuit","danger","eau partout","est tombé","est tombée","sont tombés","une chute","fait une chute","paierai pas","payerai pas","réglerai pas","paie pas","paye pas","pas payer cette","pas payer la","pas payer tant","refuse de payer","refuse de régler","rembours","avis négatif","mauvais avis","mauvaise pub","assureur","menaç","voleur","poursuiv","vous attaquer","paierai rien","payerai rien","pas un centime","bloque le paiement","retiens le solde","retenir le solde","une étoile","explos","étincel","ça fume","pris une décharge","décharge électrique","s’est coupé","s’est blessé","signalement","réclame","remise en état","conflit","dénonce","fui","fuy","perd de l’eau","perdent de l’eau","perte d’eau","urgen","urgemment","goutte","suinte","déborde","sous l’eau","de l’eau par terre","plus de chauffage","plus d’eau chaude","au plus vite","pressant","entendre parler de moi","retiens le paiement","rendez-moi mon argent","une honte","avis sur google","plombs ont sauté","pris feu","court-jus","coule du","ça coule","goutte du","escroqu","plaindre","plains","dommages et","consommateur","bâcl","mal fait","fraude","disjoncteur saute","ça disjoncte","disjoncte sans","refui","refuy","humidit","humide","eau coule","coule le long","ruissel","s’échapp","s’écoul","eau qui sort","eau sort","eau se perd","de l’eau sous","lâche de l’eau","crache de l’eau","pisse de l’eau","se vide tout seul","perd du liquide","perte de liquide","c’est pressé","est très pressé","suis pressé","odeur"];
const MOTS_ENTIERS = ["gaz","procès","police","accident","accidents","pompiers","juge","ufc","vol","samu","urssaf"];
const FAUSSE_URGENCE = / (?:pas d|sans|aucune|rien d) urgen[a-z]*| pas urgent[a-z]*| (?:sans|aucun|pas de) degats?| une chute de (?:neige|pluie|grele|feuilles)/g;
const PERTE_D_EAU = / (?:perd[a-z]*|pert|pertes?)(?: (?!chauffe )[a-z0-9]+){0,5}? (?:d |de l |de |l |d l )?d?l?eaux? /;
const APPAREIL_PERD = / (?:chauffe eau|ballon|cumulus|radiateur|radiateurs|robinet|chaudiere|tuyau|tuyaux|joint|wc|evier|lavabo|siphon|vanne) (?:perd|perdent|perdait|perdaient|a perdu|ont perdu)(?= $| pouvez| pourriez| depuis| encore| toujours| beaucoup| un peu| pas mal| partout| de partout| par terre| par le| sous| a nouveau| merci)/;
const NOMS_NEUTRES = /\b(?:chaudieres?|cuisinieres?|plaques?(?:[^a-z0-9]+de[^a-z0-9]+cuisson)?)[^a-z0-9]+(?:(?:a|au)[^a-z0-9]+)?gaz\b|\bbruleurs?\b|\battestations?[^a-z0-9]+(?:d[^a-z0-9]+)?(?:assurances?[^a-z0-9]*)?(?:decennale|rc pro|responsabilite civile)?/g;
const OFFRES = {"gratuit":{"plateforme":false,"relances_auto":false},"essentiel":{"plateforme":false,"relances_auto":false},"studio":{"plateforme":true,"relances_auto":false},"signature":{"plateforme":true,"relances_auto":true},"entreprise":{"plateforme":true,"relances_auto":true},"business":{"plateforme":true,"relances_auto":true},"*":{"plateforme":false,"relances_auto":false}};
const ESCALADE_DEFAUT = ["urgence","fuite","degat des eaux","inondation","gaz","assurance"];
const MAX_PAR_PASSAGE = 100;
const MAX_ENVOIS = 80;
const MESSAGES_RELUS = 10;
const DELAI_REGISTRE_MS = 3 * 86400000;
const ADRESSE_SURE = /^[A-Za-z0-9._+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/;
const passage = $('Passage').first().json.passage;
const maintenant = Date.parse(passage);
const lire = (nom) => $(nom).all().map((i) => i.json).filter((x) => x && typeof x === 'object');
const texte = (v) => (typeof v === 'string' ? v : '');
const offre = (plan) => (typeof plan === 'string' && Object.prototype.hasOwnProperty.call(OFFRES, plan) ? OFFRES[plan] : OFFRES['*']);
const sansAccents = (s) => texte(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const enMots = (s) => ' ' + sansAccents(s).replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const RACINES_TOUJOURS = MOTS_TOUJOURS.map((m) => [m, enMots(m).trim()]);
const RACINES_ENTIERES = MOTS_ENTIERS.map((m) => [m, enMots(m).trim()]);
// lib/pilote/regles.ts : sujetEscalade (les sujets qu'aucun réglage ne retire, puis les mots de l'artisan).
const sujetEscalade = (messages, motsArtisan) => {
  const artisan = (Array.isArray(motsArtisan) ? motsArtisan : []).filter((m) => typeof m === 'string').map((m) => [m, sansAccents(m).trim()]).filter(([, k]) => k !== '');
  for (const brut of messages) {
    if (typeof brut !== 'string' || !brut.trim()) continue;
    const mots = enMots(brut).replace(NOMS_NEUTRES, ' ').replace(FAUSSE_URGENCE, ' ').replace(/ {2,}/g, ' ');
    for (const [m, k] of RACINES_TOUJOURS) if (k && mots.includes(' ' + k)) return m;
    for (const [m, k] of RACINES_ENTIERES) if (k && mots.includes(' ' + k + ' ')) return m;
    if (PERTE_D_EAU.test(mots)) return 'perte d’eau';
    if (APPAREIL_PERD.test(mots)) return 'perte d’eau';
    if (mots.includes(' ca sent ')) return 'ça sent';
    const brutSansNoms = sansAccents(brut).replace(NOMS_NEUTRES, ' ');
    for (const [m, k] of artisan) if (brutSansNoms.includes(k)) return m;
  }
  return null;
};
const par = (liste, cle) => { const o = {}; liste.forEach((x) => { if (typeof x[cle] === 'string') (o[x[cle]] = o[x[cle]] || []).push(x); }); return o; };
const dues = lire('Lire relances dues').filter((r) => typeof r.id === 'string' && typeof r.lead_id === 'string' && typeof r.planifiee_le === 'string' && Date.parse(r.planifiee_le) <= maintenant)
  .sort((a, b) => Date.parse(a.planifiee_le) - Date.parse(b.planifiee_le) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)).slice(0, MAX_PAR_PASSAGE);
const leads = {}; lire('Lire demandes').forEach((l) => { if (typeof l.id === 'string') leads[l.id] = l; });
const comptes = {}; lire('Lire comptes').forEach((c) => { if (typeof c.id === 'string') comptes[c.id] = c; });
const reglages = {}; lire('Lire reglages').forEach((r) => { if (typeof r.artisan_id === 'string') reglages[r.artisan_id] = r; });
const suspendus = new Set(lire('Lire suspensions').map((s) => s.artisan_id).filter((x) => typeof x === 'string'));
const entrants = par(lire('Lire messages entrants'), 'lead_id');
const devisDe = par(lire('Lire devis'), 'lead_id');
const facturesDe = par(lire('Lire factures'), 'devis_id');
const actionsDe = par(lire('Lire actions assistant'), 'objet_id');
const rappelsDe = par(lire('Lire rappels CRM'), 'devis_id');
const impayesDe = par(lire('Lire relances impayes'), 'facture_id');
const exclusions = lire('Lire exclusions').filter((e) => typeof e.artisan_id === 'string');
// lib/relancesRegistre.ts : le dossier d'une conversation (ses devis, leurs factures) a-t-il été relancé par un AUTRE chemin depuis moins de
// 3 jours ? (sauf « conversation » : les relances de conversation gardent leur calendrier). Une date illisible compte comme récente.
const registreRecent = (lead) => {
  const devis = (devisDe[lead.id] || []).filter((d) => d.artisan_id === lead.artisan_id);
  const devisIds = devis.map((d) => d.id);
  const factureIds = devisIds.flatMap((id) => (facturesDe[id] || []).filter((f) => f.artisan_id === lead.artisan_id).map((f) => f.id));
  const traces = [
    ...[...devisIds, ...factureIds].flatMap((id) => (actionsDe[id] || []).map((a) => a.maj_le)),
    ...devisIds.flatMap((id) => (rappelsDe[id] || []).map((r) => r.envoye_le)),
    ...factureIds.flatMap((id) => (impayesDe[id] || []).map((r) => r.envoyee_le)),
  ];
  return traces.some((le) => { const t = Date.parse(String(le)); return !Number.isFinite(t) || maintenant - t < DELAI_REGISTRE_MS; });
};
// « Ne plus relancer ce client » (migration 0185) : une exclusion en cours sur la conversation, ou sur un client de ses devis.
const exclu = (lead) => {
  const clients = new Set((devisDe[lead.id] || []).filter((d) => d.artisan_id === lead.artisan_id).map((d) => d.client_id).filter((c) => typeof c === 'string'));
  return exclusions.some((e) => e.artisan_id === lead.artisan_id && ((typeof e.lead_id === 'string' && e.lead_id === lead.id) || (typeof e.client_id === 'string' && clients.has(e.client_id))));
};
// lib/relances.ts : sujetDuFil — les 10 derniers messages ENTRANTS et la demande d'origine, avec les mots de l'artisan.
const sujetDuFil = (lead) => {
  const reg = reglages[lead.artisan_id];
  const mots = reg && Object.prototype.hasOwnProperty.call(reg, 'escalade_mots') ? reg.escalade_mots : ESCALADE_DEFAUT;
  const derniers = (entrants[lead.id] || []).slice().sort((a, b) => Date.parse(b.sent_at) - Date.parse(a.sent_at) || (a.id < b.id ? 1 : a.id > b.id ? -1 : 0)).slice(0, MESSAGES_RELUS).map((m) => m.contenu);
  return sujetEscalade([...derniers, lead.message ?? null], mots);
};
const actif = (prefs) => !prefs || typeof prefs !== 'object' || prefs.proposition !== false;
const sortie = [];
const contactes = new Set();
let envois = 0;
let plafond = false;
const rendre = (r, effet, decision, motif, extra) => sortie.push({ json: { courrier: 'decision', relance_id: r.id, lead_id: r.lead_id, rang: r.rang ?? 1, effet, decision, motif, mot: null, envoi: null, avis: null, simulation: true, ...extra } });
for (const r of dues) {
  // Plafond du jour atteint plus haut : l'ancien passage s'arrête (break), le reste de la liste reste dû.
  if (plafond) { rendre(r, 'reste_due', 'reste_due', 'plafond'); continue; }
  const lead = leads[r.lead_id];
  if (!lead) { rendre(r, 'annulee', 'annulee', 'lead_absent'); continue; }
  if (lead.statut !== 'repondu') { rendre(r, 'annulee', 'annulee', 'lead_clos'); continue; }
  if (lead.prise_en_main === true) { rendre(r, 'annulee', 'annulee', 'prise_en_main'); continue; }
  const artisan = comptes[lead.artisan_id];
  if (!artisan) { rendre(r, 'annulee', 'annulee', 'compte_absent'); continue; }
  if (!offre(artisan.is_founder ? 'business' : artisan.plan).plateforme) { rendre(r, 'annulee', 'annulee', 'sans_plateforme'); continue; }
  if (exclu(lead)) { rendre(r, 'annulee', 'annulee', 'exclu'); continue; }
  if (suspendus.has(lead.artisan_id)) { rendre(r, 'reste_due', 'reste_due', 'suspendu'); continue; }
  if (artisan.leads_pause === true) { rendre(r, 'reste_due', 'reste_due', 'pause_artisan'); continue; }
  if (contactes.has(lead.id)) { rendre(r, 'reste_due', 'reste_due', 'un_seul_par_passage'); continue; }
  if (registreRecent(lead)) { rendre(r, 'reste_due', 'reste_due', 'registre_recent'); continue; }
  const sujet = sujetDuFil(lead);
  if (sujet) { rendre(r, 'annulee', 'annulee', 'escalade', { mot: sujet }); continue; }
  if (artisan.is_founder) { rendre(r, 'annulee', 'annulee', 'fondateur'); continue; }
  if (!offre(artisan.plan).relances_auto) {
    // Studio : la relance est PRÉPARÉE (messages.etat = 'proposition'), l'artisan est prévenu ; elle part au clic, jamais seule.
    contactes.add(lead.id);
    let avis;
    const dest = texte(artisan.email).trim();
    if (!dest) avis = 'sans_email';
    else if (!actif(artisan.notifications)) avis = 'desactive';
    else if (/\.invalid$/i.test(dest)) avis = 'adresse_de_test';
    else if (!ADRESSE_SURE.test(dest)) avis = 'adresse_atypique';
    else if (envois >= MAX_ENVOIS) avis = 'plafond';
    else { envois++; avis = 'proposition'; }
    rendre(r, 'prise', 'prepare', 'studio', { avis });
    continue;
  }
  // Signature : la relance part seule, avec la mention d'IA (courriers.js), seulement si le contact est une adresse e-mail.
  const contact = texte(lead.contact);
  let envoi;
  if (!contact.includes('@')) envoi = contact ? 'pas_un_courriel' : 'sans_coordonnees';
  else if (/\.invalid$/i.test(contact.trim())) { envoi = 'adresse_de_test'; contactes.add(lead.id); }
  else if (!ADRESSE_SURE.test(contact.trim())) { rendre(r, 'reste_due', 'reste_due', 'adresse_atypique'); continue; }
  else if (envois >= MAX_ENVOIS) { plafond = true; rendre(r, 'reste_due', 'reste_due', 'plafond'); continue; }
  else { envois++; envoi = 'a_envoyer'; contactes.add(lead.id); }
  rendre(r, 'prise', 'part_seul', 'signature', { envoi });
}
return sortie;

// presti-relances : la place du MODÈLE. ÉPINGLÉ : ce nœud n'appelle rien, il rend un texte d'exemple fixe pour chaque relance dont la décision est
// « prepare » (Studio) ou « part_seul » (Signature), rien pour les autres. Le jour où le workflow est publié, ce nœud est remplacé par le modèle
// (le prompt de lib/ai.ts:694-711, brief « Avant la bascule »). La garde commune n'admet encore aucun nœud de modèle dans un workflow du
// chantier 4 (scripts/n8n-specs-qa.mjs, liste blanche de la famille c4).
const TEXTE_EPINGLE = 'Relance exemple.';
return $input.all().map((i) => ({ json: { ...i.json, modele: 'epingle', texte_modele: i.json.courrier === 'decision' && (i.json.decision === 'prepare' || i.json.decision === 'part_seul') ? TEXTE_EPINGLE : null } }));

// presti-relances : ce qu'envoie le chemin codé quand la décision est « part seul » (app/api/cron/relances/route.ts:204-218) — la relance au
// prospect, au nom de l'artisan, avec la mention d'IA (lib/mentionAssistant.ts:14-17) — ou « prepare » (:186-203) : l'avis « Relance prête à
// valider » à l'artisan. Le texte vient du modèle (épinglé) ; sans texte, le repli de lib/ai.ts:1155-1180 (relanceTemplate). Code pur :
// rien n'est envoyé ici, rien n'est écrit. Copie figée contrôlée par scripts/relances-n8n-qa.mjs, cas par cas contre la vraie route.
const EXPEDITEUR = 'contact@prestiapp.fr';
const MENTION = 'Message rédigé et envoyé automatiquement par l’assistant';
const texte = (v) => (typeof v === 'string' ? v : '');
const nettoyer = (v) => texte(v).replace(/[\r\n<>"]/g, '').trim().slice(0, 70) || 'Votre artisan';
const uneLigne = (v) => texte(v).replace(/[\r\n]+/g, ' ');
const relanceTemplate = (nomArtisan, nomProspect, rang) => {
  const a = texte(nomArtisan).trim() || 'votre artisan';
  const p = texte(nomProspect).trim() ? texte(nomProspect).trim() + ', ' : '';
  if (rang <= 1) return 'Bonjour ' + p + '\n\nJe reviens vers vous suite à votre demande. Souhaitez-vous qu\'on avance ensemble ? Je reste à votre disposition pour convenir d\'un rendez-vous ou répondre à vos questions.\n\nBien à vous,\n' + a;
  if (rang === 2) return 'Bonjour ' + p + '\n\nJe me permets de vous relancer concernant votre projet. Si c\'est toujours d\'actualité, dites-moi simplement quand vous êtes disponible et je m\'organise.\n\nBien à vous,\n' + a;
  return 'Bonjour ' + p + '\n\nSans nouvelles de votre part, je mets votre demande de côté pour l\'instant — mais n\'hésitez pas à me recontacter dès que vous le souhaitez, je serai ravi de vous aider.\n\nBien à vous,\n' + a;
};
const lire = (nom) => $(nom).all().map((i) => i.json).filter((x) => x && typeof x === 'object' && typeof x.id === 'string');
const leads = {}; lire('Lire demandes').forEach((l) => { leads[l.id] = l; });
const comptes = {}; lire('Lire comptes').forEach((c) => { comptes[c.id] = c; });
const sortie = [];
for (const d of $('Modele epingle').all().map((i) => i.json).filter((x) => x && x.courrier === 'decision')) {
  const lead = leads[d.lead_id];
  const artisan = lead ? comptes[lead.artisan_id] : null;
  if ((d.decision === 'part_seul' || d.decision === 'prepare') && (!lead || !artisan)) { sortie.push({ json: { courrier: 'ignore', relance_id: d.relance_id, raison: 'demande ou compte introuvable', simulation: true } }); continue; }
  const rang = d.rang ?? 1;
  const nom = texte(artisan && artisan.nom);
  const brut = texte(d.texte_modele).trim();
  const relance = brut || (artisan ? relanceTemplate(artisan.nom ?? null, lead.nom_prospect, rang) : '');
  const decision = { ...d, texte_relance: d.decision === 'prepare' || d.decision === 'part_seul' ? relance : null };
  if (d.decision === 'part_seul' && d.envoi === 'a_envoyer') {
    const court = nom.replace(/[\r\n]+/g, ' ').trim().slice(0, 70);
    const mention = MENTION + (court ? ' de ' + court : '') + '.';
    const sec = relance.trimEnd();
    const corps = sec.endsWith(mention) ? sec.slice(0, sec.length - mention.length).replace(/\s*—\s*$/, '') : sec;
    sortie.push({ json: { courrier: 'relance', relance_id: d.relance_id, lead_id: d.lead_id, cle: 'relance:' + d.relance_id, simulation: true,
      a: texte(lead.contact).trim(), de: nettoyer(nom.trim() || 'Votre artisan') + ' <' + EXPEDITEUR + '>', repondre_a: texte(artisan.email).trim(),
      sujet: uneLigne(nom ? 'Suite à votre demande — ' + nom : 'Suite à votre demande'),
      corps, de_artisan: court ? ' de ' + court : '',
      texte: corps + '\n\n—\n' + mention } });
  }
  if (d.decision === 'prepare' && d.avis === 'proposition') {
    sortie.push({ json: { courrier: 'avis', relance_id: d.relance_id, lead_id: d.lead_id, cle: 'avis:' + d.relance_id, simulation: true,
      a: texte(artisan.email).trim(), de: 'Presti <' + EXPEDITEUR + '>', repondre_a: EXPEDITEUR,
      sujet: uneLigne('Relance prête à valider — ' + (texte(lead.nom_prospect) || 'votre client')),
      texte: (texte(lead.nom_prospect) || 'Votre client') + ' n\'a pas encore répondu. Une relance est prête dans votre espace (Messages) : relisez-la et validez-la d\'un clic pour qu\'elle parte.' } });
  }
  sortie.push({ json: decision });
}
return sortie;

parameters.text:
={{ $json.corps }}

—
Message rédigé et envoyé automatiquement par l’assistant{{ $json.de_artisan }}.
